import{_ as l,C as r,o,c as s,aw as a,E as t}from"./chunks/framework.DLufY-ao.js";const n="/workbook/assets/crp1.B9ay6R-M.png",c="/workbook/assets/crp2.DNrA-fQD.png",v=JSON.parse('{"title":"Critical Rendering Path","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/critical-rendering-path/rendering/critical-rendering-path.md","filePath":"wiki/dev-commit/js/critical-rendering-path/rendering/critical-rendering-path.md"}'),d={name:"wiki/dev-commit/js/critical-rendering-path/rendering/critical-rendering-path.md"};function h(u,i,m,p,g,S){const e=r("v-breadcrumbs");return o(),s("div",null,[i[0]||(i[0]=a('<h1 id="critical-rendering-path" tabindex="-1">Critical Rendering Path <a class="header-anchor" href="#critical-rendering-path" aria-label="Permalink to &quot;Critical Rendering Path&quot;">​</a></h1><h2 id="critical-rendering-path-1" tabindex="-1">Critical Rendering Path <a class="header-anchor" href="#critical-rendering-path-1" aria-label="Permalink to &quot;Critical Rendering Path&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определения</p><ul><li><strong>Critical Rendering Path</strong> (Критический путь рендеринга) - последовательность шагов, необходимая для первого отображения страницы (прежде чем HTML-ответ от сервера будет преобразован в пиксели на экране)</li><li>Знания о CRP необходимы для улчшения производительности</li><li><strong>Style Calculation</strong> - вычисление стилей для каждого элемента</li></ul></div><ul><li>Render <em>16ms</em></li></ul><h2 id="принцип-работы" tabindex="-1">Принцип работы <a class="header-anchor" href="#принцип-работы" aria-label="Permalink to &quot;Принцип работы&quot;">​</a></h2><img src="'+n+'" width="650px"><hr><img src="'+c+'" width="650px"><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><h3 id="_1-построение-dom-дерева-✅" tabindex="-1">1. Построение DOM-дерева ✅ <a class="header-anchor" href="#_1-построение-dom-дерева-✅" aria-label="Permalink to &quot;1. Построение DOM-дерева ✅&quot;">​</a></h3><ul><li>Из полученного от сервера HTML-документа формируется DOM</li></ul><div class="tip custom-block"><p class="custom-block-title">DOM</p><ul><li><strong>DOM</strong> (объектная модель документа) дерево это объект, представляющий полностью разобранную HTML-страницу. Начиная с корневого элемента html, узлы создаются для каждого элемента/текста на странице. Элементы, вложенные в другие элементы, представлены в виде дочерних узлов, и каждый узел содержит полный набор атрибутов для этого элемента</li></ul></div><ul><li>HTML может быть исполнен по частям. <em>Документ не должен быть загружен полностью</em> для того, чтобы контент начал появляться на странице</li><li><em>DOM-дерево помещается в JavaScript-объект Document</em></li></ul><hr><h3 id="_2-построение-cssom-дерева-❌" tabindex="-1">2. Построение CSSOM-дерева ❌ <a class="header-anchor" href="#_2-построение-cssom-дерева-❌" aria-label="Permalink to &quot;2. Построение CSSOM-дерева ❌&quot;">​</a></h3><ul><li>Загружаются и распознаются стили, формируется CSSOM</li><li>Строится параллельно с построением DOM</li></ul><div class="tip custom-block"><p class="custom-block-title">CSSOM</p><ul><li><strong>CSSOM</strong> (CSS Object Model) - объект, представляющий стили, связанные с DOM. Он выглядит так же как DOM, но с соответствующими стилями для каждого узла. Не имеет значения были ли стили объявлены явно или наследуются</li></ul></div><ul><li>CSS считается <em>«блокирующим обработку ресурсом»</em>. Это значит, что Render-дерево не может быть построено без полного первоначального разбора CSS</li><li>В отличии от HTML, CSS не может быть использован по частям в силу своей каскадной природы. Стили, описанные в документе ниже, могут переопределять и изменять стили, определённые ранее. Так что если мы начнём использовать CSS-стили до того, как будет разобрана таблица стилей, мы можем столкнуться с ситуацией, когда стили будут применяться неверно. Это означает, что для перехода к следующему шагу, необходимо полностью разобрать CSS</li><li><em>CSSOM перестраивается полностью каждый раз</em></li></ul><hr><h3 id="_3-запуск-javascript-❌-при-async-✅" tabindex="-1">3. Запуск JavaScript ❌ при async ✅ <a class="header-anchor" href="#_3-запуск-javascript-❌-при-async-✅" aria-label="Permalink to &quot;3. Запуск JavaScript ❌ при async ✅&quot;">​</a></h3><ul><li>JavaScript является блокирующим ресурсом для парсера. Это означает, что JavaScript блокирует разбор самого HTML-документа</li><li>Когда парсер доходит до тега <code>script</code> (не важно внутренний он или внешний), он останавливается, забирает файл (если он внешний) и запускает его</li><li>JavaScript можно загружать асинхронно, указав атрибут <code>async</code>, для того, чтобы избежать блокировки парсера</li></ul><hr><h3 id="_4-создание-render-tree" tabindex="-1">4. Создание Render Tree <a class="header-anchor" href="#_4-создание-render-tree" aria-label="Permalink to &quot;4. Создание Render Tree&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Render-дерево</strong> - совокупность DOM и CSSOM</li></ul></div><ul><li>Это дерево, которое даёт представление о том, что в конечном итоге будет отображено на странице. Это означает, что оно захватывает только видимый контент и не включает, например, элементы, которые были скрыты с помощью CSS-правила display: none или &lt;head&gt;</li></ul><hr><h3 id="_5-layout-генерация-раскладки" tabindex="-1">5. Layout (генерация раскладки) <a class="header-anchor" href="#_5-layout-генерация-раскладки" aria-label="Permalink to &quot;5. Layout (генерация раскладки)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Раскладка</strong> - для каждого элемента Render Tree определяютяс его размеры и рассчитывается его положение на странице</li></ul></div><ul><li>Вычисление взаимного расположения и размеров элементов на странице, плюс компоновка всего</li><li>Браузеры используют поточный метод (<code>flow</code>), при котором в большинстве случаев достаточно одного прохода для размещения всех элементов (для таблиц проходов требуется больше)</li><li>Определяется размер видимой области документа (viewport), которая обеспечивает контекст для стилей CSS, зависимых от него, например, проценты или единицы viewport</li><li>Размер viewport определяется метатэгом, находящемся в head документа или, если тэг не представлен, будет использовано стандартное значение viewport 980px</li></ul><hr><h3 id="_6-paint-отрисовка-в-браузере" tabindex="-1">6. Paint (отрисовка в браузере) <a class="header-anchor" href="#_6-paint-отрисовка-в-браузере" aria-label="Permalink to &quot;6. Paint (отрисовка в браузере)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Отрисовка</strong> - видимый контент страницы преобразуется в пиксели и отрисовывается на экране</li></ul></div><ul><li>Время, которое займет этот этап, зависит как от величины DOM, так и от того, какие стили применяются. Некоторые стили требуют больше усилий, чтобы быть применёнными, чем другие. Например, сложное градиентное фоновое изображение потребует больше времени, чем простой сплошной цвет на фоне</li></ul><h2 id="chrome-dev-tools" tabindex="-1">Chrome Dev Tools <a class="header-anchor" href="#chrome-dev-tools" aria-label="Permalink to &quot;Chrome Dev Tools&quot;">​</a></h2>',34)),t(e,{items:["Chrome Dev Tools","Performance","Event Log"]}),t(e,{items:["Chrome Dev Tools","Network","Record network activity"]}),i[1]||(i[1]=a("<ol><li><strong>Send Request</strong> - GET-запрос, отправленный для index.html</li><li><strong>Parse HTML and Send Request</strong> - начать разбор HTML и построение DOM. Отправить GET запрос для style.css и main.js</li><li><strong>Parse Stylesheet</strong> - CSSOM, созданный для style.css</li><li><strong>Evaluate Script</strong> - вычислить (выполнить) main.js</li><li><strong>Layout</strong> - генерация раскладки, основанной на значении метатега viewport</li><li><strong>Paint</strong> - отрисовка пикселей в документе</li></ol>",1))])}const b=l(d,[["render",h]]);export{v as __pageData,b as default};
